$(function() {
    function a() {
        $$jquery("#print-btn").on("click", function() {
            return $$jquery(MAIN_CONTAINER_SELECTOR).print(), !1
        })
    }
    var b = $("#sticky-nav-bar"),
        c = $("#top-navbar-id"),
        d = $("#back-to-top");
    b.hide(),
    $(window).scroll(function() {
        var a = c.position().top,
            e = $(window).scrollTop();
        e > a ? (d.fadeIn(), 0 == b.is(":visible") && b.fadeIn()) : (d.fadeOut(), 1 == b.is(":visible") && b.fadeOut())
    }),
    setToolTips(),
    $("#vaada a, #info-main a").click(function(a) {
        a.stopPropagation()
    }),
    $(".accordion-toggle").on("click", function() {
        setAccessability_AriaExpanded($(this))
    }).on("keyup", function(a) {
        a.keyCode == $$jquery.ui.keyCode.ENTER && $(this).click()
    }),
    a()
});

$('#mailModal').appendTo('body');

// Some host sites load Bootstrap CSS without the responsive max-width rules,
// so #mailModal .modal-dialog ends up width:auto / max-width:none and spans
// the full viewport. Re-apply Bootstrap's small-modal width.
// Also force opacity:1 when .show is present — Raanana ships BS3-style CSS
// (which fades via the .in class) but BS5 JS, which toggles .show instead,
// leaving the modal stuck at opacity:0 (display:block but invisible).
$('<style>').text(
    '#mailModal .modal-dialog{max-width:300px;margin:1.75rem auto;}' +
    '#mailModal.show{opacity:1;}'
).appendTo('head');

// On sites running Bootstrap 5 the button's legacy data-toggle="modal" /
// data-target attributes are ignored (BS5 expects data-bs-toggle / data-bs-target),
// so clicking #mail-btn does nothing. Open the modal explicitly; on older Bootstrap
// the built-in handler also runs and .modal('show') is a no-op when already shown.
$(document).on('click', '#mail-btn', function() {
    $('#mailModal').modal('show');
});

// Enter inside the email input was submitting the surrounding <form> (which has
// no action, so the browser navigated to the page URL and wiped the modal state).
// Treat Enter as clicking "שלח" instead, and block the implicit form submit.
$(document).on('keydown', '#mailAddress', function(e) {
    if (e.which === 13 || e.keyCode === 13) {
        e.preventDefault();
        e.stopPropagation();
        var btn = $('#mailModal .modal-footer .btn-primary')[0];
        if (btn) btn.click();
        return false;
    }
});
$(document).on('submit', '#mailModal form', function(e) {
    e.preventDefault();
    return false;
});

// Re-entry guard: rapid duplicate triggers (sticky-key auto-repeat, accidental
// double Enter, double click on שלח) would otherwise each fire a request and
// send a duplicate email. Block while a request is in flight.
var _mailSendInProgress = false;
function btnSendMail_Clicked(e) {
    if (_mailSendInProgress) return !1;
    var modal = $("#mailModal"),
        input = $("#mailAddress"),
        mail = (input.val() || "").trim(),
        re = /^(([^<>()\[\]\\.,;:\s@"]+(\.[^<>()\[\]\\.,;:\s@"]+)*)|(".+"))@((\[[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}])|(([a-zA-Z\-0-9]+\.)+[a-zA-Z]{2,}))$/;
    if (!mail) return alert("יש להזין כתובת מייל"), !1;
    if (!re.test(mail)) return alert("יש להזין כתובת מייל תקינה"), !1;
    var url = "{0}{1}SendBakashaMail&siteid={2}&b={3}&e={4}&arguments=siteid,b,e".format(siteBaseURL, xpaBaseURL, getSiteId(), e, mail);
    _mailSendInProgress = true;
    $.ajax({
        type: "GET",
        url: url,
        success: function() {
            modal.modal("hide");
            input.val("");
            alert("המייל נשלח בהצלחה");
        },
        error: function() {
            alert("שליחת המייל נכשלה, אנא נסה שנית");
        },
        complete: function() {
            _mailSendInProgress = false;
        }
    });
    return !1;
}

function setAriaExpanded(a) {
    a.hasClass("collapsed") ? a.attr("aria-expanded", "false") : a.attr("aria-expanded", "true")
}

function toggleAriaExpanded(a) {
    "true" === a.attr("aria-expanded") ? a.attr("aria-expanded", "false") : a.attr("aria-expanded", "true")
}

$(document).on("click", '[data-toggle="collapse"]', function(e) {
    e.preventDefault();
    e.stopImmediatePropagation();
    var $this = $(this);
    var targetSelector = $this.attr("data-target") || $this.attr("href");
    if (targetSelector) {
        var $target = $(targetSelector);
        if ($target.hasClass("show") || $target.hasClass("in")) {
            $target.removeClass("show in");
            if (!$target.hasClass("collapse")) {
                $target.addClass("collapse");
            }
            $target.css("height", "");
            $this.addClass("collapsed");
            $this.attr("aria-expanded", "false");
        } else {
            $target.addClass("show in");
            $target.removeClass("collapse");
            $target.css("height", "");
            $this.removeClass("collapsed");
            $this.attr("aria-expanded", "true");
        }
    }
});
